package pgsmoke_test

import (
	"testing"

	"foundry.test/goway/integrations/seeding"
	"foundry.test/goway/models"
	"github.com/weiloon1234/Foundry-Go/database/orm"
	"github.com/weiloon1234/Foundry-Go/database/seed"
	"github.com/weiloon1234/Foundry-Go/testkit/postgres"
)

func TestORMSeederAndPageAdapters(t *testing.T) {
	db := postgres.Isolate(t).Open(t)
	ctx := t.Context()
	_, err := db.Exec(ctx, `CREATE TABLE write_records (code bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text NOT NULL, enabled boolean NOT NULL DEFAULT true, note text, amount numeric NOT NULL DEFAULT 0)`)
	must(t, err)
	registry, err := seed.New(seeding.RecordSeeder("seeded"))
	must(t, err)
	result, err := registry.Run(ctx, db)
	must(t, err)
	if len(result.Committed) != 1 || result.Committed[0] != "fixture.records" {
		t.Fatal("seeder did not commit", result)
	}
	page, err := orm.Paginate(ctx, db, models.WriteRecords.Query(), orm.Page(1, 10))
	must(t, err)
	if page.Total != 1 || len(page.Items) != 1 || page.Items[0].Name != "seeded" || !page.Items[0].Enabled {
		t.Fatal("seeder lost ORM defaults or page metadata", page)
	}
	cursor, err := orm.CursorPaginate(ctx, db, models.WriteRecords.Query(), orm.CursorRequest[models.WriteRecord]{Size: 1})
	must(t, err)
	if len(cursor.Items) != 1 || cursor.Items[0].Code != page.Items[0].Code {
		t.Fatal("cursor adapter changed rows")
	}
}
